// ── Driver scenarios ─────────────────────────────────────────────────────

/// The n-th getter call (a 60 Hz frame): silence for 0.3 s, a loud phrase until
/// 1.5 s, a quiet tail until 3 s, then silence (the generator's `levelFn`).
fn scripted_level() -> LevelSource {
    let calls = Arc::new(AtomicUsize::new(0));
    LevelSource::getter(move || {
        let n = calls.fetch_add(1, Ordering::SeqCst) + 1;
        let t = n as f64 / 60.0;
        if t < 0.3 {
            0.0
        } else if t < 1.5 {
            0.8
        } else if t < 3.0 {
            0.2
        } else {
            0.0
        }
    })
}

fn scenario_glow(name: &str) -> VoiceGlow {
    match name {
        "default-dark" => VoiceGlow::new().level_source(scripted_level()),
        "pill-light" => VoiceGlow::new()
            .kind(VoiceGlowType::Pill)
            .theme(VoiceGlowTheme::Light)
            .level_source(scripted_level())
            .border_radius(22.0)
            .color_variant(ColorVariant::Ocean),
        "mobile-processing" => VoiceGlow::new()
            .kind(VoiceGlowType::Mobile)
            .level_source(scripted_level())
            .border_radius(24.0)
            .processing(true)
            .color_variant(ColorVariant::Sunset),
        "reduced-motion" => VoiceGlow::new()
            .level_source(scripted_level())
            .reduced_motion(true),
        "motion-fixed" => VoiceGlow::new()
            .level(0.3)
            .color_variant(ColorVariant::Forest)
            .motion_fixed(VoiceGlowMotion {
                gather: 0.8,
                offset: 0.5,
                stretch: 0.5,
                held_level: 0.6,
                corner_follow: 0.5,
            }),
        "custom-light" => VoiceGlow::new()
            .theme(VoiceGlowTheme::Light)
            .level_source(scripted_level())
            .scale(0.7)
            .bands(false)
            .bend(30.0)
            .band_tail(0.2)
            .flow(-40.0)
            .core_light(2.5)
            .hue_range(Degrees::new(10.0))
            .hue_duration(Duration::from_secs_f64(4.0))
            .color_variant(ColorVariant::Mono)
            .attack(Duration::from_secs_f64(0.1))
            .release(Duration::from_secs_f64(0.3))
            .threshold(0.1)
            .idle(0.4)
            .border_radius(30.0)
            .colors_css(["#ff0000", "rgb(0, 255, 0)"])
            .band_colors(BandColors::new().core(parse_hex("#102030")))
            .softness(1.4)
            .glow_size(1.3)
            .distortion(0.0)
            .stroke_opacity(0.5),
        other => panic!("scenario {other}"),
    }
}

fn check_config(name: &str, glow: &VoiceGlow, want: &Value, t: f64) {
    let c = glow.config(ResolvedTheme::Dark);
    macro_rules! chk {
        ($($field:ident => $key:literal),+ $(,)?) => {
            $( close(c.$field, num(&want[$key], $key), t, &format!("{name} config.{}", $key)); )+
        };
    }
    chk! {
        sensitivity => "sensitivity", threshold => "threshold", attack => "attack", release => "release",
        idle => "idle", breathe_duration => "breatheDuration", reach => "reach", spread => "spread",
        flow => "flow", lobe_spacing => "lobeSpacing", bend => "bend", band_strength => "bandStrength",
        band_width => "bandWidth", band_position => "bandPosition", band_curve => "bandCurve",
        band_spread => "bandSpread", band_skew => "bandSkew", band_offset => "bandOffset",
        band_tail => "bandTail", band_tail_position => "bandTailPosition", band_tail_curve => "bandTailCurve",
        band_tail_overflow => "bandTailOverflow", band_aberration => "bandAberration",
        range_width => "rangeWidth", range_height => "rangeHeight", distortion => "distortion",
        core_light => "coreLight", scale => "scale", radius => "radius", hue_range => "hueRange",
        hue_duration => "hueDuration",
    }
    assert_eq!(c.bands, want["bands"].as_bool().unwrap(), "{name} bands");
    assert_eq!(
        c.static_colors,
        want["staticColors"].as_bool().unwrap(),
        "{name} staticColors"
    );
    assert_eq!(
        c.reduced_motion,
        want["reducedMotion"].as_bool().unwrap(),
        "{name} reducedMotion"
    );
    assert_eq!(
        format!("{:?}", c.theme).to_lowercase(),
        want["theme"].as_str().unwrap(),
        "{name} theme"
    );
    let triple = |rgb: Rgb| format!("{}, {}, {}", rgb.r, rgb.g, rgb.b);
    let bc = &want["bandColors"];
    assert_eq!(
        triple(c.band_colors.core),
        bc["core"].as_str().unwrap(),
        "{name} band core"
    );
    assert_eq!(
        triple(c.band_colors.above),
        bc["above"].as_str().unwrap(),
        "{name} band above"
    );
    assert_eq!(
        triple(c.band_colors.mid),
        bc["mid"].as_str().unwrap(),
        "{name} band mid"
    );
    assert_eq!(
        triple(c.band_colors.below),
        bc["below"].as_str().unwrap(),
        "{name} band below"
    );
}

fn check_style(name: &str, glow: &VoiceGlow, scenario: &Value, t: f64) {
    let c = glow.config(ResolvedTheme::Dark);
    let s = &c.style;
    let want = &scenario["style"];
    close(
        s.stroke_opacity,
        num(&want["strokeOpacity"], "so"),
        t,
        &format!("{name} strokeOpacity"),
    );
    close(
        s.inner_opacity,
        num(&want["innerOpacity"], "io"),
        t,
        &format!("{name} innerOpacity"),
    );
    close(
        s.bloom_opacity,
        num(&want["bloomOpacity"], "bo"),
        t,
        &format!("{name} bloomOpacity"),
    );
    close(
        s.brightness,
        num(&want["brightness"], "b"),
        t,
        &format!("{name} brightness"),
    );
    close(
        s.saturation,
        num(&want["saturation"], "s"),
        t,
        &format!("{name} saturation"),
    );
    close(
        s.bloom_blur,
        num(&want["bloomBlur"], "bb"),
        t,
        &format!("{name} bloomBlur"),
    );
    close(
        c.strength,
        num(&want["strength"], "str"),
        t,
        &format!("{name} strength"),
    );
    let round = |v: f64| (v + 0.5).floor();
    for (layer, key) in [
        (&s.stroke, "strokeLobe0"),
        (&s.inner, "innerLobe0"),
        (&s.bloom, "bloomLobe0"),
    ] {
        let w = &want[key];
        assert_eq!(
            round(f64::from(LOBES[0].w) * layer.width_scale),
            num(&w["w"], "w"),
            "{name} {key} w"
        );
        assert_eq!(
            round(f64::from(LOBES[0].h) * layer.height_scale),
            num(&w["h"], "h"),
            "{name} {key} h"
        );
        assert_eq!(
            layer.fade_percent,
            num(&w["fade"], "fade"),
            "{name} {key} fade"
        );
    }
    match (&s.core_light, want["core"].is_null()) {
        (None, true) => {}
        (Some(core), false) => {
            let w = &want["core"];
            assert_eq!(
                core.solid_percent,
                num(&w["solid"], "solid"),
                "{name} solid"
            );
            assert_eq!(core.mid_percent, num(&w["mid"], "mid"), "{name} mid");
            assert_eq!(
                core.mid_alpha,
                num(&w["midAlpha"], "midAlpha"),
                "{name} midAlpha"
            );
            assert_eq!(core.end_percent, num(&w["end"], "end"), "{name} end");
            assert_eq!(
                core.rx,
                num(&want["coreEllipse"]["rx"], "rx"),
                "{name} core rx"
            );
            assert_eq!(
                core.ry,
                num(&want["coreEllipse"]["ry"], "ry"),
                "{name} core ry"
            );
            assert_eq!(
                core.opacity_base,
                num(&want["coreOpacity"]["base"], "base"),
                "{name} core base"
            );
            assert_eq!(
                core.opacity_gain,
                num(&want["coreOpacity"]["gain"], "gain"),
                "{name} core gain"
            );
            assert_eq!(
                core.blur,
                num(&want["coreBlur"], "blur"),
                "{name} core blur"
            );
        }
        (ours, theirs_null) => {
            panic!("{name}: core light mismatch (ours {ours:?}, upstream null: {theirs_null})")
        }
    }
    close(
        s.noise_frequency.0,
        num(&want["noiseFrequency"][0], "nf0"),
        t,
        &format!("{name} noise x"),
    );
    close(
        s.noise_frequency.1,
        num(&want["noiseFrequency"][1], "nf1"),
        t,
        &format!("{name} noise y"),
    );
    for (i, col) in scenario["colors"].as_array().unwrap().iter().enumerate() {
        assert_eq!(
            s.colors[i],
            parse_rgb_fn(col.as_str().unwrap()),
            "{name} lobe colour {i}"
        );
    }
}

fn check_frame(name: &str, frame: &VoiceGlowFrame, want: &Value, distortion_on: bool, t: f64) {
    let n = want["n"].as_u64().unwrap();
    let ctx = |what: &str| format!("{name} step {n} {what}");
    let v = &want["vars"];
    close(
        frame.level,
        num(&want["level"], "level"),
        t,
        &ctx("onLevel"),
    );
    close(frame.level, num(&v["level"], "level"), t, &ctx("level"));
    close(frame.center_offset, num(&v["cx"], "cx"), t, &ctx("cx"));
    close(frame.mask_width, num(&v["mw"], "mw"), t, &ctx("mw"));
    close(frame.bend_height, num(&v["bh"], "bh"), t, &ctx("bh"));
    close(
        frame.bend_strength,
        num(&v["bendA"], "bendA"),
        t,
        &ctx("bendA"),
    );
    close(frame.corner_lift, num(&v["cy"], "cy"), t, &ctx("cy"));
    close(frame.glow, num(&v["glow"], "glow"), t, &ctx("glow"));
    close(frame.height_scale, num(&v["h"], "h"), t, &ctx("h"));
    close(frame.width_scale, num(&v["w"], "w"), t, &ctx("w"));
    close(frame.hue_drift, num(&v["hue"], "hue"), t, &ctx("hue"));
    for (i, lobe) in frame.lobes.iter().enumerate() {
        close(
            lobe.x,
            num(&v[format!("x{i}")], "x"),
            t,
            &ctx(&format!("x{i}")),
        );
        close(
            lobe.amplitude,
            num(&v[format!("l{i}")], "l"),
            t,
            &ctx(&format!("l{i}")),
        );
        close(
            lobe.lift,
            num(&v[format!("y{i}")], "y"),
            t,
            &ctx(&format!("y{i}")),
        );
    }

    // The distortion filter.
    if distortion_on {
        let warp_off = want["warpOff"].as_bool().unwrap();
        assert_eq!(frame.distortion.is_none(), warp_off, "{}", ctx("warp off"));
        if let (Some(d), false) = (frame.distortion, warp_off) {
            let w = &want["displace"];
            close(d.amount, num(&w["amount"], "amount"), t, &ctx("displace"));
            close(d.noise_offset.0, num(&w["dx"], "dx"), t, &ctx("noise dx"));
            close(d.noise_offset.1, num(&w["dy"], "dy"), t, &ctx("noise dy"));
        }
    } else {
        assert!(frame.distortion.is_none(), "{}", ctx("no distortion"));
    }

    // The band line and its strokes.
    let strokes = want["strokes"].as_array().unwrap();
    match &frame.band {
        None => assert!(strokes.is_empty(), "{}", ctx("band hidden")),
        Some(band) => {
            assert_eq!(strokes.len(), 17, "{}", ctx("stroke count"));
            let line = &frame.band_line;
            let first = line[0];
            let mut expected = vec![(
                band.halo.width,
                band.halo.alpha,
                band.halo_color,
                (0.0, 0.0),
            )];
            for ridge in &band.ridges {
                for s in &ridge.strokes {
                    expected.push((s.width, s.alpha, ridge.color, ridge.offset));
                }
            }
            for (i, (w, a, rgb, off)) in expected.into_iter().enumerate() {
                let s = &strokes[i];
                close(
                    w,
                    num(&s["width"], "width"),
                    t,
                    &ctx(&format!("stroke {i} width")),
                );
                close(
                    a,
                    num(&s["alpha"], "alpha"),
                    t,
                    &ctx(&format!("stroke {i} alpha")),
                );
                // The stop prints alpha with 12 digits; the colour is the same.
                assert_eq!(
                    [rgb.r, rgb.g, rgb.b],
                    [
                        s["rgb"][0].as_u64().unwrap() as u8,
                        s["rgb"][1].as_u64().unwrap() as u8,
                        s["rgb"][2].as_u64().unwrap() as u8
                    ],
                    "{}",
                    ctx(&format!("stroke {i} colour"))
                );
                close(
                    band.end_fade,
                    num(&s["fade"], "fade"),
                    t,
                    &ctx(&format!("stroke {i} fade")),
                );
                close(
                    first.0 + off.0,
                    num(&s["first"][0], "fx"),
                    t,
                    &ctx(&format!("stroke {i} start x")),
                );
                close(
                    first.1 + off.1,
                    num(&s["first"][1], "fy"),
                    t,
                    &ctx(&format!("stroke {i} start y")),
                );
                assert_eq!(
                    s["len"].as_u64().unwrap() as usize,
                    line.len(),
                    "{}",
                    ctx("path length")
                );
            }
        }
    }
    if let Some(pts) = want["bandLine"].as_array() {
        assert_eq!(
            frame.band_line.len(),
            pts.len(),
            "{}",
            ctx("band line length")
        );
        for (i, (ours, theirs)) in frame.band_line.iter().zip(pts).enumerate() {
            close(ours.0, num(&theirs[0], "x"), t, &ctx(&format!("band x{i}")));
            close(ours.1, num(&theirs[1], "y"), t, &ctx(&format!("band y{i}")));
        }
    }
}

fn run_scenario(scenario: &Value, t: f64) {
    let name = scenario["name"].as_str().unwrap();
    let host = HostSize::new(
        num(&scenario["host"]["w"], "w"),
        num(&scenario["host"]["h"], "h"),
    );
    let glow = scenario_glow(name);
    check_config(name, &glow, &scenario["config"], t);
    check_style(name, &glow, scenario, t);

    let mut engine = VoiceGlowEngine::new(&glow, ResolvedTheme::Dark);
    let frames = scenario["frames"].as_array().unwrap();
    let last = frames.last().unwrap()["n"].as_u64().unwrap();
    let distortion_on = engine.config().distortion > 0.0;
    let mut next = 0;
    for n in 1..=last {
        if name == "mobile-processing" && n == 151 {
            // The reference's getter reports processing off after 150 calls.
            engine.reconfigure(&glow.clone().processing(false), ResolvedTheme::Dark);
        }
        let frame = engine.step(FRAME_STEP, host);
        if frames[next]["n"].as_u64().unwrap() == n {
            check_frame(name, &frame, &frames[next], distortion_on, t);
            next += 1;
        }
    }
    assert_eq!(next, frames.len(), "{name}: every sampled frame compared");
}

