#[test]
fn voice_glow_processing_sweep_matches_the_reference_function() {
    // Same dt sequence as the generator's rAF clock: first call 0, then 1/60.
    let g = golden();
    let scenario = &g["scenarios"][2];
    let tuning = ProcessingTuning::for_type(VoiceGlowType::Mobile);
    let mut p = VoiceProcessing::new();
    let mut m = VoiceGlowMotion::default();
    for n in 1..=150 {
        m = p.step(true, &tuning, false, FRAME_STEP);
        if n == 150 {
            // The driver wrote these as --vb-cx / --vb-mw at step 150.
            let frame = scenario["frames"]
                .as_array()
                .unwrap()
                .iter()
                .find(|f| f["n"] == 150)
                .unwrap();
            let span = LOBE_SPAN * 1.35 * 1.25;
            close(
                m.offset * span / 2.0,
                num(&frame["vars"]["cx"], "cx"),
                tol(&g),
                "processing cx",
            );
            close(
                1.0 - m.gather * 0.45,
                num(&frame["vars"]["mw"], "mw"),
                tol(&g),
                "processing mw",
            );
        }
    }
    assert!(m.gather > 0.99);
}
